parameters.jsCode:
const form = $input.first().json;

const allowedCodeTypes = [
  'Building Code',
  'Residential Code',
  'Fire Code',
  'Mechanical Code',
  'Plumbing Code',
  'Electrical Code'
];

const location = (form['Location'] || '').toString().trim();
const codeType = (form['Code Type'] || '').toString().trim();

if (location.length < 3 || location.length > 200) {
  throw new Error('Invalid location: must be 3-200 characters.');
}

// A useful US location has either a space (e.g., "Renton WA") or digits (ZIP or street number).
// This rejects useless inputs like a bare state code ("WA") which would burn a GPT-4o agent run.
const hasSpace = /\s/.test(location);
const hasDigits = /\d/.test(location);
if (!hasSpace && !hasDigits) {
  throw new Error('Invalid location: please provide a city + state, ZIP code, or full address (e.g., "Renton WA", "98168").');
}

if (!allowedCodeTypes.includes(codeType)) {
  throw new Error(`Invalid code type. Must be one of: ${allowedCodeTypes.join(', ')}`);
}

return [{
  json: {
    location,
    codeType,
    geocode_prompt: `Identify the US city and state for the location "${location}". Respond with exactly "City, Full State Name" (e.g., "Renton, Washington"). If the location is ambiguous, not in the United States, or you cannot determine it, respond with exactly "UNKNOWN". Do not add explanations or any other text.`
  }
}];

const aiResponse = $input.first().json;
const validated = $('Validate Input').item.json;

const raw = (aiResponse?.message?.content || '').toString().trim();

// Require the model to return exactly "City, Full State" (letters, spaces, dots, apostrophes, hyphens).
// If the format is off, fall back to the raw location rather than passing malformed data to the agent.
const formatRegex = /^[A-Za-z .'\-]+,\s*[A-Za-z ]+$/;
const isValid = raw && raw.toUpperCase() !== 'UNKNOWN' && formatRegex.test(raw);
const resolvedCity = isValid ? raw : validated.location;

return [{
  json: {
    location: validated.location,
    codeType: validated.codeType,
    city: resolvedCity,
    geocode_succeeded: isValid
  }
}];

assignments.value:
=Research the current {{ $json.codeType }} for this US jurisdiction:

- Location entered: {{ $json.location }}
- Resolved jurisdiction: {{ $json.city }}
- Code type: {{ $json.codeType }}

Follow the search strategy in your instructions and ground every claim in retrieved sources.

parameters.jsonBody:
={
  "q": "{{ $fromAI('query', 'The search query string for finding building code information. Be specific and include the city, state, and code type.', 'string') }}",
  "num": 10
}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "executive_summary": {
      "type": "string",
      "description": "2-3 sentence overview of the current code status for this jurisdiction."
    },
    "base_code": {
      "type": "string",
      "description": "The base code adopted, e.g. '2021 Uniform Plumbing Code'."
    },
    "adopting_authority": {
      "type": "string",
      "description": "The body that adopted it, e.g. 'Washington State Building Code Council'."
    },
    "state_code_reference": {
      "type": "string",
      "description": "State administrative code reference, e.g. 'Chapter 51-56 WAC'."
    },
    "local_amendments": {
      "type": "string",
      "description": "Summary of city-specific amendments, or 'None found' if not located."
    },
    "results": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "properties": {
          "title": { "type": "string" },
          "link": { "type": "string" },
          "snippet": { "type": "string" },
          "source_type": {
            "type": "string",
            "enum": ["city", "state", "publisher", "other"]
          }
        },
        "required": ["title", "link", "snippet"]
      }
    }
  },
  "required": ["executive_summary", "base_code", "adopting_authority", "local_amendments", "results"]
}

parameters.jsCode:
// Cleans agent output before rendering:
//   1. Unwraps `{ output, intermediateSteps }` shape produced when returnIntermediateSteps=true.
//   2. Dedupes results by URL.
//   3. Drops URLs whose host is not on the allowlist (.gov, .us, recognized publishers).
//   4. Re-tags `source_type` for publisher domains (the model occasionally mis-tags these).
//   5. Sorts city/state first, publishers next, other last; caps at 6.
//
// Output shape is unchanged downstream: `{ output: { executive_summary, base_code, ... results } }`,
// so Format HTML Output keeps working without modification.

const raw = $input.first().json;
const ai = raw?.output ?? raw;
const intermediateSteps = raw?.intermediateSteps ?? null;

const PUBLISHER_DOMAINS = [
  'codepublishing.com',
  'municode.com',
  'ecode360.com',
  'iccsafe.org'
];

function hostOf(url) {
  try { return new URL(url).hostname.toLowerCase(); }
  catch { return ''; }
}

function isPublisher(host) {
  return PUBLISHER_DOMAINS.some(d => host === d || host.endsWith('.' + d));
}

function isAllowed(host) {
  if (!host) return false;
  if (host.endsWith('.gov') || host.endsWith('.us')) return true;
  return isPublisher(host);
}

function retag(host, modelTag) {
  if (isPublisher(host)) return 'publisher';
  if (host.endsWith('.gov') || host.endsWith('.us')) {
    // Trust the model's city/state distinction for gov domains; default to 'city' if missing.
    return (modelTag === 'state' || modelTag === 'city') ? modelTag : 'city';
  }
  return 'other';
}

const rawResults = Array.isArray(ai?.results) ? ai.results : [];
const seen = new Set();
const cleaned = [];
let dropped = 0;

for (const r of rawResults) {
  const url = String(r?.link || '').trim();
  if (!url) { dropped++; continue; }
  if (seen.has(url)) { dropped++; continue; }
  const host = hostOf(url);
  if (!isAllowed(host)) { dropped++; continue; }
  seen.add(url);
  cleaned.push({
    title: String(r?.title || 'Untitled'),
    link: url,
    snippet: String(r?.snippet || ''),
    source_type: retag(host, r?.source_type)
  });
}

const order = { city: 1, state: 2, publisher: 3, other: 4 };
cleaned.sort((a, b) => (order[a.source_type] || 9) - (order[b.source_type] || 9));
const final = cleaned.slice(0, 6);

return [{
  json: {
    output: {
      executive_summary: ai?.executive_summary || 'No summary available.',
      base_code: ai?.base_code || 'Not identified',
      adopting_authority: ai?.adopting_authority || 'Not identified',
      state_code_reference: ai?.state_code_reference || 'Not specified',
      local_amendments: ai?.local_amendments || 'None found',
      results: final
    },
    filter_stats: {
      input_count: rawResults.length,
      kept: final.length,
      dropped
    },
    intermediateSteps
  }
}];

const formData = $('User Input Form').item.json;
const location = formData['Location'];
const codeType = formData['Code Type'];

const raw = $input.first().json;
const ai = raw?.output ?? raw;

const escape = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const safeUrl = (u) => {
  const s = String(u ?? '').trim();
  return /^https?:\/\//i.test(s) ? s : '#';
};

const summary = escape(ai?.executive_summary || 'No summary available.');
const baseCode = escape(ai?.base_code || 'Not identified');
const authority = escape(ai?.adopting_authority || 'Not identified');
const stateRef = escape(ai?.state_code_reference || 'Not specified');
const amendments = escape(ai?.local_amendments || 'None found');
const results = Array.isArray(ai?.results) ? ai.results : [];

let html = `
<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:760px;line-height:1.55;color:#222;">
  <h2 style="color:#1a365d;margin-bottom:4px;">${escape(codeType)} &mdash; ${escape(location)}</h2>

  <h3 style="color:#2d3748;">Executive Summary</h3>
  <p>${summary}</p>

  <h3 style="color:#2d3748;">Key Adopted Code</h3>
  <ul>
    <li><strong>Base Code:</strong> ${baseCode}</li>
    <li><strong>Adopting Authority:</strong> ${authority}</li>
    <li><strong>State Reference:</strong> ${stateRef}</li>
  </ul>

  <h3 style="color:#2d3748;">Local Amendments</h3>
  <p>${amendments}</p>

  <h3 style="color:#2d3748;">Official Sources</h3>
`;

if (results.length === 0) {
  html += `<p><em>No verified sources were returned for this query. Try a more specific location (e.g., add the state) and retry.</em></p>`;
} else {
  html += '<ol>';
  for (const r of results) {
    const title = escape(r?.title || 'Untitled source');
    const link = safeUrl(r?.link);
    const snippet = escape(r?.snippet || '');
    const type = r?.source_type ? ` <span style=\"color:#718096;font-size:0.85em;\">[${escape(r.source_type)}]</span>` : '';
    html += `<li style=\"margin-bottom:10px;\"><a href=\"${link}\" target=\"_blank\" rel=\"noopener noreferrer\">${title}</a>${type}<br><em style=\"color:#4a5568;\">${snippet}</em></li>`;
  }
  html += '</ol>';
}

html += `<hr style=\"margin-top:24px;border:none;border-top:1px solid #e2e8f0;\"><p style=\"color:#a0aec0;font-size:0.8em;\">Generated by AI research agent. Always verify against the official jurisdiction website before relying on this information for permitting or construction.</p></div>`;

return [{
  json: {
    formatted: html,
    raw_ai_output: ai,
    filter_stats: raw?.filter_stats || null,
    metadata: {
      workflow: 'building-code-lookup',
      version: '2.1.0',
      generated_at: new Date().toISOString()
    }
  }
}];
